import my_memviz


class FakeTensor:
    def __init__(self, shape, dtype="torch.float32", element_size=4):
        self._shape = list(shape)
        self._dtype = dtype
        self._element_size = element_size

    @property
    def shape(self):
        return self._shape

    @property
    def dtype(self):
        return self._dtype

    def nelement(self):
        n = 1
        for s in self._shape:
            n *= s
        return n

    def element_size(self):
        return self._element_size


class FakeGradFn:
    def __init__(self, **kwargs):
        for k, v in kwargs.items():
            setattr(self, k, v)


def test_extract_saved_tensors_exists_and_returns_list():
    assert hasattr(my_memviz, "extract_saved_tensors")
    result = my_memviz.extract_saved_tensors(FakeGradFn())
    assert isinstance(result, list)

